import{_ as d,o as e,c as a,a2 as r}from"./chunks/framework.DWOyCk6h.js";const b=JSON.parse('{"title":"Editor 产品能力总览","description":"","frontmatter":{},"headers":[],"relativePath":"editor/capabilities.md","filePath":"editor/capabilities.md","lastUpdated":1785288787000}'),i={name:"editor/capabilities.md"};function o(n,t,l,s,h,c){return e(),a("div",null,[...t[0]||(t[0]=[r(`<h1 id="editor-产品能力总览" tabindex="-1">Editor 产品能力总览 <a class="header-anchor" href="#editor-产品能力总览" aria-label="Permalink to &quot;Editor 产品能力总览&quot;">​</a></h1><blockquote><p>更新日期：2026-07-20 · 与本轮产品收口结论对齐<br> 详细演进见 <a href="./iteration-evolution.html">iteration-evolution.md</a></p></blockquote><hr><h2 id="_1-产品定位" tabindex="-1">1. 产品定位 <a class="header-anchor" href="#_1-产品定位" aria-label="Permalink to &quot;1. 产品定位&quot;">​</a></h2><p>让非开发人员用拖拽搭建：</p><ol><li><strong>审批 / 业务表单</strong>（Flex）</li><li><strong>运营大屏 / 自由页面</strong>（Free）</li><li><strong>可发布、可嵌入</strong>的运行页（<code>/view/:code</code>）</li></ol><p>技术内核：Schema JSON + Widget 注册表 + 事件/联动/API/变量四大配置系统。</p><hr><h2 id="_2-能力矩阵" tabindex="-1">2. 能力矩阵 <a class="header-anchor" href="#_2-能力矩阵" aria-label="Permalink to &quot;2. 能力矩阵&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力域</th><th>能力项</th><th>状态</th><th>入口 / 证据</th></tr></thead><tbody><tr><td>搭建</td><td>Free 绝对定位画布</td><td>✅</td><td><code>layoutMode: &#39;free&#39;</code></td></tr><tr><td>搭建</td><td>Flex 流式页面</td><td>🟡</td><td>渲染 + 投放可用；容器嵌套仍单层 flatten，见 <a href="./container-nesting-decision.html">container-nesting-decision.md</a></td></tr><tr><td>搭建</td><td>85+ Widget</td><td>✅</td><td><code>widgets/</code> + registry</td></tr><tr><td>搭建</td><td>大屏 Demo 一键创建</td><td>✅</td><td>实例新建 →「运营大屏 Demo」</td></tr><tr><td>搭建</td><td>深色大屏主题</td><td>✅</td><td><code>boardThemes</code> / canvas.themePreset</td></tr><tr><td>交互</td><td>拖拽 / 缩放 / 辅助线</td><td>✅</td><td><strong>Free</strong>：EditorOverlay + useDrag；Flex 无 resize/辅助线</td></tr><tr><td>交互</td><td>Flex 部件拖入</td><td>🟡</td><td>useFlexCanvasDrop / FlexColDropZone；缺插入指示线、嵌套 2 层未落地</td></tr><tr><td>交互</td><td>撤销重做（immer）</td><td>✅</td><td>editorStore</td></tr><tr><td>交互</td><td>对齐 / 分布 / 锁定 / 隐藏</td><td>✅</td><td>useWidgetAlignment + 快捷键</td></tr><tr><td>性能</td><td>视口剔除</td><td>✅</td><td>useViewportCulling（编辑态）</td></tr><tr><td>配置</td><td>事件 / 联动 / API / 变量</td><td>✅</td><td>PropertyPanel 配置入口</td></tr><tr><td>发布</td><td>保存 / 版本 / 发布</td><td>✅</td><td>apiStore + 工具栏</td></tr><tr><td>发布</td><td>4 种交互模式</td><td>✅</td><td>edit / preview / publish-*</td></tr><tr><td>发布</td><td>URL 只读/交互切换</td><td>✅</td><td><code>?interaction=</code></td></tr><tr><td>集成</td><td>qiankun 子应用</td><td>✅</td><td>microapp + platform-shared</td></tr><tr><td>集成</td><td>postMessage 宿主协议</td><td>✅</td><td>PublishView</td></tr><tr><td>扩展</td><td>SchemaType 注册式</td><td>✅</td><td><code>type SchemaType = string</code></td></tr><tr><td>扩展</td><td>createWidgetPlugin</td><td>✅</td><td>registry.ts</td></tr><tr><td>观测</td><td>前端埋点</td><td>🟡</td><td>telemetry；缺 server/dashboard</td></tr><tr><td>国际化</td><td>vue-i18n</td><td>🟡</td><td>框架就绪；UI 覆盖不足</td></tr><tr><td>开放</td><td>Widget 市场 / 脚手架</td><td>❌</td><td>见 Backlog</td></tr></tbody></table><hr><h2 id="_3-推荐验收路径" tabindex="-1">3. 推荐验收路径 <a class="header-anchor" href="#_3-推荐验收路径" aria-label="Permalink to &quot;3. 推荐验收路径&quot;">​</a></h2><h3 id="_3-1-大屏地基-e1" tabindex="-1">3.1 大屏地基（E1） <a class="header-anchor" href="#_3-1-大屏地基-e1" aria-label="Permalink to &quot;3.1 大屏地基（E1）&quot;">​</a></h3><ol><li>打开 Editor → <strong>实例</strong> → 新建</li><li>布局选 <strong>自由布局</strong>，预设选 <strong>运营大屏 Demo（E1 验收）</strong></li><li>确认：深色背景、10+ 图表、区域筛选、实时时钟、自动刷新</li><li>切换区域为「隐藏图表」→ 图表因联动隐藏</li><li>保存 → 发布 → 打开 <code>/view/{code}?interaction=interactive</code></li></ol><h3 id="_3-2-表单-flex" tabindex="-1">3.2 表单 Flex <a class="header-anchor" href="#_3-2-表单-flex" aria-label="Permalink to &quot;3.2 表单 Flex&quot;">​</a></h3><ol><li>新建 → <strong>Flex</strong> → 表单 / 列表 / 详情模板</li><li>拖入控件，配置事件与联动</li><li>预览 → 保存发布</li></ol><h3 id="_3-3-发布态模式" tabindex="-1">3.3 发布态模式 <a class="header-anchor" href="#_3-3-发布态模式" aria-label="Permalink to &quot;3.3 发布态模式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>URL</th><th>预期</th></tr></thead><tbody><tr><td><code>/view/{code}?interaction=interactive</code></td><td>可编辑交互</td></tr><tr><td><code>/view/{code}?interaction=readonly</code></td><td>全局只读</td></tr><tr><td>另加 <code>&amp;showModeToggle=1</code></td><td>右上角可切换</td></tr></tbody></table><hr><h2 id="_4-架构速览-产品视角" tabindex="-1">4. 架构速览（产品视角） <a class="header-anchor" href="#_4-架构速览-产品视角" aria-label="Permalink to &quot;4. 架构速览（产品视角）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>设计器 EditorView</span></span>
<span class="line"><span>  ├── 左：部件库 / 树 / 模板</span></span>
<span class="line"><span>  ├── 中：EditorCanvas</span></span>
<span class="line"><span>  │     ├── Free → SchemaRender（视口剔除）+ EditorOverlay（命中全量数据）</span></span>
<span class="line"><span>  │     └── Flex → WidgetRenderer</span></span>
<span class="line"><span>  └── 右：PropertyPanel（basic / style / props + 四大配置）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>运行态 PublishView / Preview</span></span>
<span class="line"><span>  └── WidgetRenderer + eventEngine + linkage</span></span></code></pre></div><p>要点：<strong>虚拟化只影响 DOM，不影响拖拽命中</strong>（命中仍用全量 widget 数据）。</p><hr><h2 id="_5-已知缺口-产品优先级" tabindex="-1">5. 已知缺口（产品优先级） <a class="header-anchor" href="#_5-已知缺口-产品优先级" aria-label="Permalink to &quot;5. 已知缺口（产品优先级）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>优先级</th><th>缺口</th><th>影响</th></tr></thead><tbody><tr><td>P0</td><td>server <code>/telemetry</code> + dashboard</td><td>无法度量流失与卡顿</td></tr><tr><td>P1</td><td>真实 100+ widget FPS 体感验收</td><td>大屏上限仍偏「理论」</td></tr><tr><td>P1</td><td>i18n 覆盖 ≥ 80%</td><td>出海/开源受阻</td></tr><tr><td>P1</td><td>Flex 插入指示线 / span / 模式切换</td><td>Flex 编辑 chrome 弱于 free</td></tr><tr><td>P2</td><td>PropertyPanel 继续拆分；清理 WidgetRule</td><td>维护成本</td></tr><tr><td>P2</td><td>嵌套 2 层决策落地代码</td><td>决策与实现不一致（仍 flatten）</td></tr><tr><td>P3</td><td>Flex 专用交互设计稿</td><td>designer.md 拖拽流几乎仅 free</td></tr><tr><td>P3</td><td>SDK 脚手架 + Widget 市场</td><td>生态未开</td></tr></tbody></table><hr><h2 id="_6-相关文档" tabindex="-1">6. 相关文档 <a class="header-anchor" href="#_6-相关文档" aria-label="Permalink to &quot;6. 相关文档&quot;">​</a></h2><ul><li>根 README：<a href="./../README.html">../README.md</a></li><li>架构：<a href="./architecture.html">architecture.md</a></li><li>本轮收口：<a href="./iteration-evolution.html">iteration-evolution.md</a></li><li>贡献：<a href="./../CONTRIBUTING.html">../CONTRIBUTING.md</a></li></ul>`,28)])])}const g=d(i,[["render",o]]);export{b as __pageData,g as default};
